1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface Incident {
19	  cause: string;
20	  damages: Damage[];
21	}
22	
23	export interface ClaimStep {
24	  op: "claim";
25	  /** Zero-based index of the quote step that created the policy. */
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export type Step = QuoteStep | ClaimStep;
31	
32	export interface Customer {
33	  yearsWithMHPCO: number;
34	}
35	
36	export interface Scenario {
37	  customer: Customer;
38	  steps: Step[];
39	}
40	
41	export interface QuoteResult {
42	  premium: number;
43	}
44	
45	export interface ClaimResult {
46	  payout: number;
47	  remainingCap: number;
48	}
49	
50	export interface ScenarioResults {
51	  results: (QuoteResult | ClaimResult)[];
52	}
53	
54	const PROCESSING_FEE = 5;
55	const FIRST_INSURANCE_SURCHARGE = 0.1;
56	const CURSE_SURCHARGE = 0.5;
57	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const LOYALTY_DISCOUNT = 0.2;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
62	
63	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
64	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
65	
66	/** The two rates the tariff sets for each item type. */
67	interface ItemTariff {
68	  basePremium: number;
69	  insuranceValue: number;
70	}
71	
72	/** The item types the MHPCO insures. Any other type is unknown to the tariff. */
73	const TARIFF: Record<string, ItemTariff> = {
74	  sword: { basePremium: 100, insuranceValue: 1000 },
75	  amulet: { basePremium: 60, insuranceValue: 600 },
76	  staff: { basePremium: 80, insuranceValue: 800 },
77	  potion: { basePremium: 40, insuranceValue: 400 },
78	  rune: { basePremium: 25, insuranceValue: 250 },
79	  moonstone: { basePremium: 25, insuranceValue: 250 },
80	};
81	
82	const DEDUCTIBLE = 100;
83	const CAP_MULTIPLIER = 2;
84	const STRONG_ENCHANTMENT_THRESHOLD = 8;
85	const STRONG_ENCHANTMENT_REIMBURSEMENT = 0.5;
86	
87	const COMPONENT_TYPES = ["rune", "moonstone"];
88	const BLOCK_SIZE = 3;
89	const BLOCK_BASE_PREMIUM = 60;
90	
91	const isComponent = (type: string): boolean => COMPONENT_TYPES.includes(type);
92	
93	const countByType = (items: Item[]): Map<string, number> => {
94	  const counts = new Map<string, number>();
95	
96	  for (const item of items) {
97	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
98	  }
99	
100	  return counts;
101	};
102	
103	/** Exactly BLOCK_SIZE alike components form a building block. */
104	const formsBuildingBlock = (type: string, count: number): boolean =>
105	  isComponent(type) && count === BLOCK_SIZE;
106	
107	const tariffFor = (type: string): ItemTariff => {
108	  const tariff = TARIFF[type];
109	
110	  if (tariff === undefined) {
111	    throw new Error(`unknown item type: ${type}`);
112	  }
113	
114	  return tariff;
115	};
116	
117	const itemBasePremium = (type: string): number => tariffFor(type).basePremium;
118	
119	const itemInsuranceValue = (type: string): number => tariffFor(type).insuranceValue;
120	
121	/** Alike items are priced together so a building block can be recognised. */
122	const groupBasePremium = (type: string, count: number): number =>
123	  formsBuildingBlock(type, count)
124	    ? BLOCK_BASE_PREMIUM
125	    : count * itemBasePremium(type);
126	
127	/** The policy base premium is the sum of the base premiums of its items. */
128	const policyBasePremium = (items: Item[]): number =>
129	  [...countByType(items)].reduce(
130	    (total, [type, count]) => total + groupBasePremium(type, count),
131	    0,
132	  );
133	
134	const isCursed = (item: Item): boolean => item.cursed === true;
135	
136	const isHighlyEnchanted = (item: Item): boolean =>
137	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
138	
139	/**
140	 * Item-specific surcharges stack additively, as fractions of the item's base
141	 * premium.
142	 */
143	const itemSurchargeRate = (item: Item): number =>
144	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
145	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
146	
147	/**
148	 * Item-specific modifiers apply to the base premium of the affected item,
149	 * not to the policy total.
150	 */
151	const itemSurcharges = (items: Item[]): number =>
152	  items.reduce(
153	    (total, item) =>
154	      total + itemBasePremium(item.type) * itemSurchargeRate(item),
155	    0,
156	  );
157	
158	const isLoyalCustomer = (customer: Customer): boolean =>
159	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
160	
161	/**
162	 * Policy-wide modifiers, as fractions of the policy base premium. Each is an
163	 * amount added to (or, when negative, subtracted from) that base premium, so
164	 * modifiers stack additively rather than compounding.
165	 */
166	const policyModifierRates = (
167	  customer: Customer,
168	  isFollowUpContract: boolean,
169	): number[] => [
170	  FIRST_INSURANCE_SURCHARGE,
171	  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT : 0,
172	  isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT : 0,
173	];
174	
175	const policyModifiers = (
176	  basePremium: number,
177	  customer: Customer,
178	  isFollowUpContract: boolean,
179	): number =>
180	  policyModifierRates(customer, isFollowUpContract).reduce(
181	    (total, rate) => total + basePremium * rate,
182	    0,
183	  );
184	
185	const quotePremium = (
186	  step: QuoteStep,
187	  customer: Customer,
188	  isFollowUpContract: boolean,
189	): number => {
190	  const basePremium = policyBasePremium(step.items);
191	
192	  return roundUp(
193	    basePremium +
194	      itemSurcharges(step.items) +
195	      policyModifiers(basePremium, customer, isFollowUpContract) +
196	      PROCESSING_FEE,
197	  );
198	};
199	
200	/**
201	 * Every contract after the customer's first is a follow-up. Only quote steps
202	 * create contracts, so this counts preceding quotes rather than preceding steps.
203	 */
204	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
205	  precedingSteps.some((step) => step.op === "quote");
206	
207	/** Payouts are rounded down (in the MHPCO's favour), ignoring float noise. */
208	const roundDown = (amount: number): number =>
209	  Math.floor(Number(amount.toFixed(6)));
210	
211	/** The insurance sum is the sum of the items' insurance values. */
212	const insuranceSum = (items: Item[]): number =>
213	  items.reduce((total, item) => total + itemInsuranceValue(item.type), 0);
214	
215	const isStronglyEnchanted = (item: Item): boolean =>
216	  (item.enchantment ?? 0) >= STRONG_ENCHANTMENT_THRESHOLD;
217	
218	/**
219	 * The reimbursement clauses decide how much of the damage is reimbursed,
220	 * before the deductible is applied.
221	 */
222	const reimbursementRate = (item: Item): number =>
223	  isStronglyEnchanted(item) ? STRONG_ENCHANTMENT_REIMBURSEMENT : 1;
224	
225	const damagePayout = (damage: Damage, item: Item): number =>
226	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
227	
228	/** A policy pays out at most CAP_MULTIPLIER times its insurance sum. */
229	const policyCap = (policy: QuoteStep): number =>
230	  insuranceSum(policy.items) * CAP_MULTIPLIER;
231	
232	/** The insured item a damage entry refers to, matched by item type. */
233	const damagedItem = (damage: Damage, items: Item[]): Item => {
234	  const item = items.find((insured) => insured.type === damage.itemType);
235	
236	  if (item === undefined) {
237	    throw new Error(`item not covered by the policy: ${damage.itemType}`);
238	  }
239	
240	  return item;
241	};
242	
243	const incidentPayout = (incident: Incident, items: Item[]): number =>
244	  roundDown(
245	    incident.damages.reduce(
246	      (total, damage) => total + damagePayout(damage, damagedItem(damage, items)),
247	      0,
248	    ),
249	  );
250	
251	/** The payout is limited to what remains of the policy's cap. */
252	const claimResult = (
253	  incident: Incident,
254	  policy: QuoteStep,
255	  remainingCap: number,
256	): ClaimResult => {
257	  const payout = Math.min(incidentPayout(incident, policy.items), remainingCap);
258	
259	  return { payout, remainingCap: remainingCap - payout };
260	};
261	
262	/**
263	 * A scenario is walked step by step, because a claim draws on what earlier
264	 * claims left of its policy's cap. The caps of the policies quoted so far are
265	 * the only state carried from one step to the next.
266	 */
267	type RemainingCaps = Map<number, number>;
268	
269	const quoteStepResult = (
270	  step: QuoteStep,
271	  index: number,
272	  scenario: Scenario,
273	  remainingCaps: RemainingCaps,
274	): QuoteResult => {
275	  remainingCaps.set(index, policyCap(step));
276	
277	  return {
278	    premium: quotePremium(
279	      step,
280	      scenario.customer,
281	      isFollowUpContract(scenario.steps.slice(0, index)),
282	    ),
283	  };
284	};
285	
286	const claimStepResult = (
287	  step: ClaimStep,
288	  scenario: Scenario,
289	  remainingCaps: RemainingCaps,
290	): ClaimResult => {
291	  const policy = scenario.steps[step.policy] as QuoteStep;
292	  const result = claimResult(
293	    step.incident,
294	    policy,
295	    remainingCaps.get(step.policy) as number,
296	  );
297	
298	  remainingCaps.set(step.policy, result.remainingCap);
299	
300	  return result;
301	};
302	
303	export const runScenario = (scenario: Scenario): ScenarioResults => {
304	  const remainingCaps: RemainingCaps = new Map();
305	
306	  return {
307	    results: scenario.steps.map((step, index) =>
308	      step.op === "quote"
309	        ? quoteStepResult(step, index, scenario, remainingCaps)
310	        : claimStepResult(step, scenario, remainingCaps),
311	    ),
312	  };
313	};
